// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;
    Log logContract;

    function setUp() public {
        logContract = new Log();
        c = new Private_Bank(address(logContract));
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1 wei, 100 ether);
        CashOutRecorder recorder = new CashOutRecorder();

        vm.deal(address(recorder), amount);
        vm.prank(address(recorder));
        c.Deposit{value: amount}();

        vm.prank(address(recorder));
        c.CashOut(amount);

        assertTrue(recorder.lastCalldataLength() == 0);
    }
}

contract CashOutRecorder {
    uint256 private _lastCalldataLength;

    receive() external payable {}

    fallback() external payable {
        _lastCalldataLength = msg.data.length;
    }

    function lastCalldataLength() external view returns (uint256) {
        return _lastCalldataLength;
    }
}
